index 00000000..f49e7912
--- /dev/null
+++ b/libs/features/lazy/bacteria-game/src/lib/guest/lab-pass-card.component.ts
@@ -0,0 +1,169 @@
+import {
+  ChangeDetectionStrategy,
+  Component,
+  computed,
+  inject,
+  output,
+} from '@angular/core';
+import { MatButtonModule } from '@angular/material/button';
+import { MatIconModule } from '@angular/material/icon';
+import { ACHIEVEMENT_XP } from '@wolsok/feat-shared-bacteria-engine';
+import { achievementKeys } from '../i18n/game-texts';
+import { TranslatePipe } from '../i18n/translate.pipe';
+import { LabPassStepId } from './lab-pass';
+import { LAB_PASS_ACHIEVEMENT, LabPass } from './lab-pass.service';
+import { GUEST_IDLE_DAYS } from './guest-visits';
+import { SignIn } from './sign-in.service';
+
+/** Where a step of the pass is done, outside the card. */
+export type LabPassPage = 'profile' | 'friends';
+
+const PAGE_OF: Readonly<
+  Record<Exclude<LabPassStepId, 'sign-in'>, LabPassPage>
+> = {
+  profile: 'profile',
+  motto: 'profile',
+  friend: 'friends',
+};
+
+/** Where each step's cell sits in the dish, around its centre. */
+const CELLS = [
+  { x: 14, y: 14 },
+  { x: 26, y: 14 },
+  { x: 14, y: 26 },
+  { x: 26, y: 26 },
+] as const;
+
+/**
+ * The Lab Pass in the main menu: a dish whose cells fill step by step, the
+ * steps, and the next one as the card's button - signing in right here, the
+ * rest on the profile or the friends' screen. A guest whose account is due
+ * to be deleted reads it here too. Once complete, it tells the player the
+ * achievement they earned.
+ */
+@Component({
+  selector: 'feat-lazy-bac-game-lab-pass-card',
+  imports: [MatButtonModule, MatIconModule, TranslatePipe],
+  template: `
+    @let title =
+      (pass.justEarned()
+        ? 'profile.labPass.earnedTitle'
+        : 'profile.labPass.title'
+      ) | t;
+    @let achievement = achievementName | t;
+    <aside class="banner" [attr.aria-label]="title">
+      <svg class="badge dish" viewBox="0 0 40 40" aria-hidden="true">
+        <circle class="rim" cx="20" cy="20" r="18" />
+        @for (step of pass.steps(); track step.id; let i = $index) {
+          <circle
+            class="cell"
+            [class.done]="step.done"
+            [attr.cx]="cells[i].x"
+            [attr.cy]="cells[i].y"
+            r="4.5"
+          />
+        }
+      </svg>
+      <div class="text">
+        <strong class="title">{{ title }}</strong>
+        @if (pass.justEarned()) {
+          <p class="note">
+            {{ 'profile.labPass.earned' | t: { achievement, xp } }}
+          </p>
+        } @else {
+          <p class="note">
+            {{
+              'profile.labPass.progress'
+                | t: { done: pass.done(), total: pass.steps().length }
+            }}
+            · {{ 'profile.labPass.reward' | t: { achievement } }}
+          </p>
+          @if (pass.urgent()) {
+            <p class="note urgent">
+              {{ 'profile.guest.note' | t: { days: idleDays } }}
+            </p>
+          }
+        }
+      </div>
+      @if (!pass.justEarned()) {
+        <ol class="steps">
+          @for (step of pass.steps(); track step.id) {
+            <li [class.done]="step.done" [class.next]="step.id === next()">
+              <mat-icon aria-hidden="true">{{
+                step.done ? 'check_circle' : 'radio_button_unchecked'
+              }}</mat-icon>
+              {{ stepKey(step.id) | t }}
+            </li>
+          }
+        </ol>
+      }
+      <div class="actions">
+        @if (pass.justEarned()) {
+          <button
+            mat-flat-button
+            type="button"
+            class="primary"
+            (click)="pass.close()"
+          >
+            {{ 'profile.labPass.close' | t }}
+          </button>
+        } @else if (next(); as step) {
+          <button
+            mat-flat-button
+            type="button"
+            class="go primary"
+            [disabled]="step === 'sign-in' && !signIn.ready()"
+            [attr.title]="hintKey(step) | t"
+            (click)="take(step)"
+          >
+            <mat-icon>{{
+              step === 'sign-in' ? 'login' : 'arrow_forward'
+            }}</mat-icon>
+            {{ goKey(step) | t }}
+          </button>
+          <button mat-button type="button" (click)="pass.dismiss()">
+            {{ 'profile.guest.later' | t }}
+          </button>
+        }
+      </div>
+      @if (signIn.failed()) {
+        <span class="failed" role="status">{{ 'social.failed' | t }}</span>
+      }
+    </aside>
+  `,
+  styleUrl: './lab-pass-card.component.scss',
+  changeDetection: ChangeDetectionStrategy.OnPush,
+})
+export class LabPassCardComponent {
+  /** To the screen where the next step is done. */
+  public readonly open = output<LabPassPage>();
+
+  protected readonly pass = inject(LabPass);
+  protected readonly signIn = inject(SignIn);
+  protected readonly idleDays = GUEST_IDLE_DAYS;
+  protected readonly cells = CELLS;
+  protected readonly xp = ACHIEVEMENT_XP;
+  protected readonly achievementName =
+    achievementKeys(LAB_PASS_ACHIEVEMENT).name;
+  protected readonly next = computed(() => this.pass.next());
+
+  protected stepKey(id: LabPassStepId) {
+    return `profile.labPass.steps.${id}` as const;
+  }
+
+  protected goKey(id: LabPassStepId) {
+    return `profile.labPass.go.${id}` as const;
+  }
+
+  protected hintKey(id: LabPassStepId) {
+    return `profile.labPass.hints.${id}` as const;
+  }
+
+  protected take(step: LabPassStepId): void {
+    if (step === 'sign-in') {
+      void this.signIn.signIn();
+    } else {
+      this.open.emit(PAGE_OF[step]);
+    }
+  }
+}
diff --git a/libs/features/lazy/bacteria-game/src/lib/guest/lab-pass.service.ts b/libs/features/lazy/bacteria-game/src/lib/guest/lab-pass.service.ts
new file mode 100644
index 00000000..80ed30be
--- /dev/null
+++ b/libs/features/lazy/bacteria-game/src/lib/guest/lab-pass.service.ts
@@ -0,0 +1,137 @@
+import {
+  computed,
+  effect,
+  inject,
+  Injectable,
+  signal,
+  untracked,
+} from '@angular/core';
+import { AchievementId } from '@wolsok/feat-shared-bacteria-engine';
+import { injectGameAnalytics } from '../analytics/game-analytics';
+import { ProgressService } from '../progress.service';
+import { SocialService } from '../social/social.service';
+import { GameAccount } from '../storage/game-account';
+import { GuestNotice } from './guest-notice.service';
+import { labPassSteps, nextStep } from './lab-pass';
+import { SignIn } from './sign-in.service';
+
+/** The achievement the completed pass earns. */
+export const LAB_PASS_ACHIEVEMENT: AchievementId = 'lab-member';
+
+/**
+ * The Lab Pass in the main menu: its steps from what the game knows, the
+ * achievement it earns once complete, and the profile's onboarding after a
+ * sign-in. Only with the cloud: without it nobody signs in.
+ */
+@Injectable({ providedIn: 'root' })
+export class LabPass {
+  private readonly account = inject(GameAccount);
+  private readonly social = inject(SocialService);
+  private readonly progress = inject(ProgressService);
+  private readonly notice = inject(GuestNotice);
+  private readonly signIn = inject(SignIn);
+  private readonly analytics = injectGameAnalytics();
+
+  /** The pass's steps, each done or not. */
+  public readonly steps = computed(() => {
+    const player = this.account.profile();
+    const saved =
+      this.social.profileLoaded() && this.social.storedAvatar() !== null;
+    return labPassSteps({
+      signedIn: player !== null && !player.guest,
+      profileSaved: saved,
+      motto: saved && (this.social.profile()?.motto ?? '') !== '',
+      friend: this.social.friends().length > 0,
+    });
+  });
+
+  /** The first step still open, null once the pass is complete. */
+  public readonly next = computed(() => nextStep(this.steps()));
+
+  /** The steps done, for the dish's slots. */
+  public readonly done = computed(
+    () => this.steps().filter(({ done }) => done).length
+  );
+
+  /** True once this visit earned the pass's achievement. */
+  private readonly earnedNow = signal(false);
+  public readonly justEarned = this.earnedNow.asReadonly();
+
+  /** True when the player holds the achievement, earned now or before. */
+  private readonly held = computed(
+    () => this.progress.achievements()[LAB_PASS_ACHIEVEMENT] != null
+  );
+
+  /**
+   * True while the main menu shows the pass: with the cloud, once the
+   * player is known and their progress loaded, until they hold its
+   * achievement - and on, in this visit, to tell them they earned it.
+   * "Later" puts it away for two weeks.
+   */
+  public readonly visible = computed(
+    () =>
+      this.account.cloud &&
+      this.social.available &&
+      this.account.profile() !== null &&
+      this.progress.loaded() &&
+      (this.earnedNow() || (!this.held() && !this.notice.dismissedLately()))
+  );
+
+  /** True while a guest should hear that an unused guest account is deleted. */
+  public readonly urgent = this.notice.visible;
+
+  /** The sign-ins already led to the profile. */
+  private readonly onboarded = signal(0);
+  /**
+   * True when a sign-in of this visit brought a player without a profile
+   * of their own: the main menu then opens the profile to make one.
+   */
+  public readonly onboardingDue = computed(
+    () =>
+      this.signIn.signIns() > this.onboarded() &&
+      this.next() === 'profile' &&
+      this.social.profileLoaded()
+  );
+  /** True while the profile editor welcomes a player who just signed in. */
+  private readonly welcomingState = signal(false);
+  public readonly welcoming = this.welcomingState.asReadonly();
+
+  public constructor() {
+    effect(() => {
+      if (this.next() === null && this.progress.loaded() && !this.held()) {
+        untracked(() => this.earn());
+      }
+    });
+  }
+
+  /** Puts the pass away for two weeks. */
+  public dismiss(): void {
+    this.earnedNow.set(false);
+    this.notice.dismiss();
+  }
+
+  /** Closes the pass once its achievement was shown. */
+  public close(): void {
+    this.earnedNow.set(false);
+  }
+
+  /** The main menu opened the profile for the sign-in's onboarding. */
+  public startOnboarding(): void {
+    this.onboarded.set(this.signIn.signIns());
+    this.welcomingState.set(true);
+  }
+
+  /** The profile editor has welcomed the player. */
+  public endOnboarding(): void {
+    this.welcomingState.set(false);
+  }
+
+  private earn(): void {
+    if (this.progress.grantAchievement(LAB_PASS_ACHIEVEMENT)) {
+      this.earnedNow.set(true);
+      this.analytics.track('unlock_achievement', {
+        achievement_id: LAB_PASS_ACHIEVEMENT,
+      });
+    }
+  }
+}
diff --git a/libs/features/lazy/bacteria-game/src/lib/guest/lab-pass.ts b/libs/features/lazy/bacteria-game/src/lib/guest/lab-pass.ts
