559	+/**
560	+ * The Lab Pass: the steps that make a guest a member of the lab - signing
561	+ * in, a profile of their own, a motto, a first friend. Each step follows
562	+ * from what the game knows already; nothing about the pass is stored but
563	+ * the achievement it earns.
564	+ */
565	+
566	+/** The pass's steps, in the order the player takes them. */
567	+export const LAB_PASS_STEPS = [
568	+  'sign-in',
569	+  'profile',
570	+  'motto',
571	+  'friend',
572	+] as const;
573	+
574	+export type LabPassStepId = (typeof LAB_PASS_STEPS)[number];
575	+
576	+/** What the game knows that decides the steps. */
577	+export interface LabPassFacts {
578	+  /** The player signed in: no guest. */
579	+  signedIn: boolean;
580	+  /** The player saved a profile of their own. */
581	+  profileSaved: boolean;
582	+  /** The saved profile has a motto. */
583	+  motto: boolean;
584	+  /** The player has a friend. */
585	+  friend: boolean;
586	+}
587	+
588	+export interface LabPassStep {
589	+  id: LabPassStepId;
590	+  done: boolean;
591	+}
592	+
593	+const FACT_OF: Readonly<Record<LabPassStepId, keyof LabPassFacts>> = {
594	+  'sign-in': 'signedIn',
595	+  profile: 'profileSaved',
596	+  motto: 'motto',
597	+  friend: 'friend',
598	+};
599	+
600	+/** The pass's steps, each done when its fact holds. */
601	+export function labPassSteps(facts: LabPassFacts): readonly LabPassStep[] {
602	+  return LAB_PASS_STEPS.map((id) => ({ id, done: facts[FACT_OF[id]] }));
603	+}
604	+
605	+/** The first step still open, null once all are done. */
606	+export function nextStep(steps: readonly LabPassStep[]): LabPassStepId | null {
607	+  return steps.find(({ done }) => !done)?.id ?? null;
608	+}
